import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { GiftCardAdminComponent } from './gift-card-admin.component';
import { InventoryAdminComponent } from './inventory-admin.component';
import { CatalogMetadataAdminComponent } from './catalog-metadata-admin.component';
import { ProductMediaAdminComponent } from './product-media-admin.component';
import { ProductWizardComponent } from './product-wizard.component';
import { Router, NavigationEnd } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { SetupWizardComponent } from './setup-wizard.component';
import { SearchSelectComponent, SelectOption } from './search-select.component';
import { SellableSelectComponent } from './sellable-select.component';
import { COUNTRY_OPTIONS, CURRENCY_OPTIONS, LANGUAGE_OPTIONS, LOCALE_OPTIONS, TIMEZONE_OPTIONS } from './commerce-options';
import QRCode from 'qrcode';
type Product={id:string;name:string;description:string;sku:string;active:boolean;archived:boolean;seoSlug:string|null;seoTitle:string|null;seoDescription:string|null;scheduledPublishAt:string|null;variants?:Array<{id:string;name:string;sku:string;active:boolean;attributes?:Record<string,string>}>};
@Component({selector:'artio-admin',standalone:true,imports:[CommonModule,FormsModule,GiftCardAdminComponent,InventoryAdminComponent,CatalogMetadataAdminComponent,ProductMediaAdminComponent,ProductWizardComponent,SetupWizardComponent,SearchSelectComponent,SellableSelectComponent],template:`
<div *ngIf="!token && !setupChecked" class="login-page"><div class="login-card"><a class="brand">artio<span> / studio</span></a><p class="muted">Checking store setup…</p></div></div>
<artio-setup-wizard *ngIf="!token && setupChecked && setupRequired" [developerMode]="developerMode" (completed)="setupFinished($event)"></artio-setup-wizard>
<div *ngIf="!token && setupChecked && !setupRequired" class="login-page"><div class="login-card"><a class="brand">artio<span> / studio</span></a><p class="eyebrow">Commerce, thoughtfully run</p><h1>Welcome back.</h1><p class="muted">Sign in to manage your Artio store.</p><form (ngSubmit)="login()"><label>Email<input [(ngModel)]="email" name="email" type="email" autocomplete="username" required></label><label>Password<input [(ngModel)]="password" name="password" type="password" autocomplete="current-password" required></label><label *ngIf="!developerMode">Authenticator or backup code<input [(ngModel)]="mfaCode" name="mfaCode" inputmode="numeric" autocomplete="off"></label><small *ngIf="developerMode" class="muted">Local demo account is ready. Sign in to open your Artio workspace.</small><button class="primary">Sign in <span>↗</span></button></form><p class="error" *ngIf="error">{{error}}</p></div></div>
<div *ngIf="token && mfaSetupRequired" class="login-page"><div class="login-card setup-card mfa-card"><a class="brand">artio<span> / security</span></a><p class="eyebrow">REQUIRED ACCOUNT PROTECTION</p><h1>Secure your account.</h1><p class="muted">Add an authenticator app to protect administrator access. Scan the QR code, then enter the current six-digit code from the app.</p><button *ngIf="!mfaEnrollment && !mfaBackupCodes.length" class="primary" type="button" (click)="beginMfaEnrollment()">Start setup <span>↗</span></button><div *ngIf="mfaEnrollment && !mfaBackupCodes.length" class="mfa-enrollment"><div class="mfa-step"><span>1</span><div><strong>Scan this code</strong><p>Open Google Authenticator, Microsoft Authenticator, 1Password, or another TOTP app and scan the QR code.</p></div></div><div *ngIf="mfaQrCode" class="mfa-qr-frame"><img [src]="mfaQrCode" alt="QR code for adding Artio to your authenticator app"></div><details class="mfa-manual"><summary>Can't scan? Set up manually</summary><p>Enter this key in your authenticator app:</p><div class="mfa-secret-row"><code>{{mfaEnrollment.base32Secret}}</code><button type="button" class="secondary" (click)="copyMfaSecret()">{{mfaCopied?'Copied':'Copy key'}}</button></div><small>Choose time-based one-time password (TOTP) if the app asks.</small></details><div class="mfa-step mfa-code-step"><span>2</span><div><strong>Confirm it works</strong><p>Enter the current code shown in your authenticator app. Codes refresh every 30 seconds.</p></div></div><form (ngSubmit)="verifyMfaEnrollment()"><label>Six-digit verification code<input [(ngModel)]="mfaCode" name="enrollmentCode" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="000000" aria-describedby="mfa-code-help" required></label><small id="mfa-code-help" class="mfa-code-help">Enter the code from the app. A sample code such as 123456 will not work.</small><button class="primary" [disabled]="mfaCode.length!==6">Verify and enable <span>↗</span></button></form></div><div *ngIf="mfaBackupCodes.length" class="mfa-backup-panel"><div class="mfa-success-mark">✓</div><h2>Authenticator enabled.</h2><p>Save these one-time backup codes somewhere secure. Each code can be used once if you lose access to your authenticator.</p><ul><li *ngFor="let code of mfaBackupCodes"><code>{{code}}</code></li></ul><button class="primary" (click)="finishMfaSetup()">Continue to sign in <span>↗</span></button></div><p class="error" *ngIf="error" role="alert">{{error}}</p></div></div>
<div *ngIf="token && !mfaSetupRequired" class="shell" [class.mobile-nav-open]="navOpen"><a class="skip-link" href="#main-content">Skip to main content</a><aside class="sidebar" id="workspace-navigation" aria-label="Workspace navigation"><a class="brand">artio<span> / studio</span></a><button type="button" class="mobile-menu-toggle" [attr.aria-expanded]="navOpen" aria-controls="workspace-navigation" (click)="navOpen=!navOpen">{{navOpen?'Close menu ×':'Menu ☰'}}</button><p class="label">WORKSPACE</p><button [class.selected]="tab==='overview'" (click)="navigateTo('overview')">◫ &nbsp; Overview</button><button [class.selected]="tab==='products' || tab==='productNew'" (click)="navigateTo('products')">▦ &nbsp; Products</button><button [class.selected]="tab==='catalogData'" (click)="navigateTo('catalogData')">⌘ &nbsp; Catalog data</button><button [class.selected]="tab==='bundles'" (click)="navigateTo('bundles')">✳ &nbsp; Bundles</button><button [class.selected]="tab==='extensions'" (click)="navigateTo('extensions')">⬡ &nbsp; Extensions</button><button [class.selected]="tab==='pricing'" (click)="navigateTo('pricing')">◉ &nbsp; Pricing</button><button [class.selected]="tab==='inventory'" (click)="navigateTo('inventory')">▤ &nbsp; Inventory</button><button [class.selected]="tab==='orders'" (click)="navigateTo('orders')">↗ &nbsp; Orders</button><button [class.selected]="tab==='users'" (click)="navigateTo('users')">♙ &nbsp; Customers</button><button [class.selected]="tab==='giftCards'" (click)="navigateTo('giftCards')">▣ &nbsp; Gift cards</button><button [class.selected]="tab==='operations'" (click)="navigateTo('operations')">▣ &nbsp; Operations</button><button *ngIf="isSuperadmin" [class.selected]="tab==='system'" (click)="navigateTo('system')">⚙ &nbsp; System Settings</button><div class="sidebar-bottom"><span class="avatar">{{email.charAt(0).toUpperCase()}}</span><div><strong>{{email}}</strong><small>Administrator</small></div><button class="logout" (click)="logout()">↪</button></div></aside>
<main class="content" id="main-content" tabindex="-1"><header><div><p class="eyebrow">{{today | date:'EEEE, MMMM d'}}</p><h1>{{ title }}</h1></div><div class="header-actions"><a href="http://localhost:4200" target="_blank">View storefront ↗</a><span class="workspace-badge">Artio workspace</span></div></header>
<section *ngIf="tab==='overview'"><div class="welcome"><div><p class="eyebrow">YOUR STORE AT A GLANCE</p><h2>Your store. In focus.</h2><p>A calm view of what’s happening across your store today.</p></div><div class="welcome-mark">✳</div></div><div class="metrics"><article><span>Catalog products</span><strong>{{overviewProductTotal}}</strong><small>Across your catalogue</small></article><article><span>Bundles</span><strong>{{bundles.length}}</strong><small>In your collection</small></article><article><span>Orders</span><strong>{{overviewOrderTotal}}</strong><small>Across your store</small></article><article><span>Price entries</span><strong>{{prices.length}}</strong><small>Markets & channels</small></article></div><div class="panel"><div class="panel-heading"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>Products in your catalogue</h2></div><button class="link-button" (click)="navigateTo('products')">View all →</button></div><div class="row" *ngFor="let product of overviewProducts"><span class="dot-icon">{{product.name.charAt(0)}}</span><div class="row-main"><strong>{{product.name}}</strong><small>{{product.sku}}</small></div><span class="pill" [class.inactive]="!product.active">{{product.active?'Active':'Inactive'}}</span></div><p *ngIf="!overviewProducts.length" class="empty">Your catalogue is ready for its first product.</p></div></section>
<artio-product-wizard *ngIf="tab==='productNew'" (cancel)="navigateTo('products')" (created)="productCreated($event)"></artio-product-wizard>
<section *ngIf="tab==='products'" class="catalog-page"><div class="page-intro"><div><p class="eyebrow">YOUR CATALOG</p><h2>Made to stand out.</h2><p>Build, organize and refine your product collection.</p></div><button class="primary" (click)="navigateTo('productNew')">＋ New product</button></div><div class="toolbar catalog-toolbar"><input #productCsvFile type="file" accept=".csv,text/csv" hidden (change)="importProducts($event)"><button class="link-button" (click)="productCsvFile.click()">Import CSV</button><button class="link-button" (click)="exportProducts()">Export CSV</button><label class="search">⌕ <input aria-label="Search products" [(ngModel)]="query" (keyup.enter)="resetCatalogPage()" placeholder="Search products"></label><button class="link-button" (click)="resetCatalogPage()">Search</button><select aria-label="Product status" [(ngModel)]="catalogState" (ngModelChange)="resetCatalogPage()"><option value="ALL">All products</option><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive drafts</option><option value="ARCHIVED">Archived</option></select><artio-search-select [(ngModel)]="catalogBrandId" (ngModelChange)="resetCatalogPage()" [options]="catalogBrandOptions" label="Filter by brand" placeholder="All brands"></artio-search-select><artio-search-select [(ngModel)]="catalogCategoryId" (ngModelChange)="resetCatalogPage()" [options]="catalogCategoryOptions" label="Filter by category" placeholder="All categories"></artio-search-select><select aria-label="Sort products by" [(ngModel)]="catalogSort" (ngModelChange)="resetCatalogPage()"><option value="updatedAt">Recently updated</option><option value="createdAt">Recently created</option><option value="name">Name</option><option value="sku">SKU</option></select><select aria-label="Sort direction" [(ngModel)]="catalogDirection" (ngModelChange)="resetCatalogPage()"><option value="desc">Descending</option><option value="asc">Ascending</option></select><button class="link-button" (click)="rebuildSearchIndex()">Rebuild search index</button></div><p class="muted" *ngIf="searchIndexStatus">{{searchIndexStatus}}</p><div class="panel" *ngIf="productImportReport"><div class="panel-heading"><div><p class="eyebrow">PRODUCT CSV IMPORT</p><h2>{{productImportReport.created}} created · {{productImportReport.updated}} updated · {{productImportReport.failed}} failed</h2></div><button class="link-button" (click)="productImportReport=null">Dismiss</button></div><p class="muted">{{productImportReport.rows}} rows processed</p><div class="row" *ngFor="let item of productImportReport.errors"><span class="row-main"><strong>Row {{item.row}} · {{item.sku||'No SKU'}}</strong><small>{{item.reason}}</small></span></div></div><div class="panel table-panel"><table><thead><tr><th>PRODUCT</th><th>SKU / VARIANT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let product of filteredProducts"><td class="product-cell"><span class="product-monogram" aria-hidden="true">{{product.name.charAt(0).toUpperCase()}}</span><strong>{{product.name}}</strong><small>{{product.description}}</small><small>SEO: {{product.seoSlug||'Not set'}}</small></td><td>{{product.sku}}<small *ngFor="let variant of product.variants">{{variant.name}} · {{variant.sku}} · {{variant.active?'Active':'Inactive'}} · {{variant.attributes|json}} <button *ngIf="!product.archived" class="link-button" (click)="editVariant(variant)">Edit options</button><button *ngIf="!product.archived" class="link-button" (click)="toggleVariant(variant)">{{variant.active?'Deactivate':'Activate'}}</button></small></td><td><span class="pill" [class.inactive]="!product.active">{{product.archived?'Archived':product.active?'Active':'Inactive'}}</span><small *ngIf="product.scheduledPublishAt">Publishes {{product.scheduledPublishAt | date:'medium'}}</small></td><td><details class="product-actions"><summary>Manage product <span>⌄</span></summary><div><button *ngIf="!product.archived" class="link-button" (click)="toggle(product)">{{product.active?'Deactivate':'Activate'}}</button><button *ngIf="!product.archived" class="link-button" (click)="archiveProduct(product)">Archive</button><button *ngIf="product.archived" class="link-button" (click)="restoreProduct(product)">Restore</button><button *ngIf="!product.archived" class="link-button" (click)="createVariant(product)">Add variant</button><button *ngIf="!product.active && !product.archived && !product.scheduledPublishAt" class="link-button" (click)="schedulePublication(product)">Schedule publish</button><button *ngIf="product.scheduledPublishAt" class="link-button" (click)="cancelPublication(product)">Cancel schedule</button><button class="link-button" (click)="editSeo(product)">SEO</button><button class="link-button" (click)="mediaProduct=product">Media</button><button class="link-button" (click)="duplicateProduct(product)">Duplicate</button><button class="link-button" (click)="editTranslations(product)">Translations</button></div></details></td></tr></tbody></table><p *ngIf="!filteredProducts.length" class="empty">No products found.</p><div class="row"><span class="row-main">{{catalogTotal}} products · Page {{catalogPage+1}} of {{catalogPages}}</span><button class="link-button" [disabled]="catalogPage===0" (click)="previousCatalogPage()">Previous</button><button class="link-button" [disabled]="catalogPage+1>=catalogPages" (click)="nextCatalogPage()">Next</button></div></div><div *ngIf="translationProduct" class="panel"><div class="panel-heading"><div><p class="eyebrow">LOCALIZED CATALOG</p><h2>{{translationProduct.name}}</h2></div><button class="link-button" (click)="translationProduct=null">Close</button></div><form class="create-form" (ngSubmit)="saveTranslation()"><select [(ngModel)]="translationLocale" name="translationLocale" (ngModelChange)="loadTranslation()"><option value="de">German · de</option><option value="it">Italian · it</option><option value="fr">French · fr</option><option value="en">English · en</option></select><input [(ngModel)]="translationDraft.name" name="localizedName" placeholder="Translated product name" required><textarea [(ngModel)]="translationDraft.description" name="localizedDescription" placeholder="Translated description" rows="3"></textarea><label>Localized canonical slug<input [(ngModel)]="translationDraft.seoSlug" name="localizedSeoSlug" placeholder="e.g. lampe-de-bureau"></label><input [(ngModel)]="translationDraft.seoTitle" name="localizedSeoTitle" maxlength="180" placeholder="Localized SEO title"><textarea [(ngModel)]="translationDraft.seoDescription" name="localizedSeoDescription" maxlength="320" placeholder="Localized SEO description" rows="2"></textarea><button class="primary">Save translation</button></form></div></section>
<section *ngIf="tab==='bundles'"><div class="toolbar"><p>Curate fixed sets or configurable bundles with live quotes.</p><button class="primary" (click)="showBundle=!showBundle">＋ New bundle</button></div><form *ngIf="showBundle" class="create-form" (ngSubmit)="createBundle()"><input [(ngModel)]="bundleDraft.name" name="bundleName" placeholder="Bundle name" required><input [(ngModel)]="bundleDraft.sku" name="bundleSku" placeholder="Bundle SKU" required><select [(ngModel)]="bundleDraft.type" name="bundleType"><option value="CONFIGURABLE">Configurable</option><option value="FIXED">Fixed</option></select><artio-sellable-select [(ngModel)]="bundleSellables" name="sellables" label="Bundle product variants" [multiple]="true"></artio-sellable-select><button class="primary">Create bundle</button></form><div class="bundle-list"><article *ngFor="let b of bundles"><div class="bundle-mark">✳</div><p class="eyebrow">{{b.type}}</p><h2>{{b.name}}</h2><span class="pill" [class.inactive]="!b.active">{{b.active?'Active':'Inactive'}}</span><button class="link-button" (click)="activateBundle(b)">{{b.active?'Deactivate':'Activate'}}</button><button class="link-button" (click)="editBundleTranslation(b)">Translations</button></article></div><div *ngIf="bundleTranslationBundle" class="panel"><div class="panel-heading"><div><p class="eyebrow">LOCALIZED CONFIGURATOR</p><h2>{{bundleTranslationBundle.name}}</h2></div><button class="link-button" (click)="bundleTranslationBundle=null">Close</button></div><form class="create-form" (ngSubmit)="saveBundleTranslation()"><select [(ngModel)]="bundleTranslationLocale" name="bundleTranslationLocale" (ngModelChange)="loadBundleTranslation()"><option value="de">German · de</option><option value="it">Italian · it</option><option value="fr">French · fr</option><option value="en">English · en</option></select><input [(ngModel)]="bundleTranslationDraft.name" name="localizedBundleName" placeholder="Translated bundle name" required><label *ngFor="let group of bundleTranslationBundle.optionGroups">{{group.name}}<input [(ngModel)]="bundleTranslationDraft.optionGroupNames[group.code]" [name]="'bundle-translation-'+group.code" placeholder="Translated option-group label" required></label><button class="primary">Save translations</button></form></div></section>
<section *ngIf="tab==='extensions'"><div class="toolbar"><p>Register trusted extensions and manage schema-defined settings.</p><button class="primary" (click)="showExtensionRegistration=!showExtensionRegistration">＋ Register extension</button></div><div class="panel table-panel"><p class="eyebrow">PLUGIN DISCOVERY</p><h2>Regional catalog</h2><p class="muted">Trusted releases appear here when registered. Recommendations without a published digest remain visible and cannot be installed yet.</p><table><thead><tr><th>PLUGIN</th><th>REGION</th><th>CAPABILITY</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let item of extensionCatalog"><td><strong>{{item.name}}</strong><small>{{item.pluginId}} · {{item.description}}</small></td><td>{{item.countryCode}} · {{item.optional?'Optional':'Recommended'}}</td><td>{{item.extensionPoints.join(', ')}}</td><td>{{item.status}}<small *ngIf="item.version">v{{item.version}}</small><button *ngIf="item.releaseRegistered && item.lifecycleState==='UNINSTALLED'" class="link-button" (click)="restoreCatalogPlugin(item)">Restore registration</button><button *ngIf="item.releaseRegistered && item.lifecycleState!=='UNINSTALLED'" class="link-button" (click)="selectCatalogPlugin(item)">Manage release</button></td></tr></tbody></table><p *ngIf="!extensionCatalog.length" class="empty">No plugins are recommended for the packaged distributions.</p></div><p class="error" *ngIf="error">{{error}}</p><p class="muted" *ngIf="extensionHealth">{{extensionHealth}}</p><form *ngIf="showExtensionRegistration" class="create-form" (ngSubmit)="registerExtension()"><textarea [(ngModel)]="extensionManifestJson" name="extensionManifest" rows="10" placeholder="Paste extension manifest JSON" required></textarea><button class="primary">Validate and register</button></form><div class="bundle-list"><article *ngFor="let extension of extensions"><div class="bundle-mark">⬡</div><p class="eyebrow">{{extension.id}}</p><h2>{{extension.name}}</h2><span class="pill">{{extension.lifecycleState}}</span><small>v{{extension.version}} · {{extension.configuredSecrets.length}} configured secret(s)</small><small>Availability: {{extension.geographicAvailability?.scope || 'GLOBAL'}}{{extension.geographicAvailability?.countries?.length ? ' · ' + extension.geographicAvailability.countries.join(', ') : ''}}</small><button *ngIf="extension.lifecycleState==='CONFIGURED' || extension.lifecycleState==='FAILED'" class="link-button" (click)="extensionAction(extension,'install')">Install</button><button *ngIf="extension.lifecycleState==='INSTALLED' || extension.lifecycleState==='DISABLED'" class="link-button" (click)="extensionAction(extension,'enable')">Enable</button><button *ngIf="extension.lifecycleState==='ENABLED'" class="link-button" (click)="extensionAction(extension,'disable')">Disable</button><button *ngIf="extension.lifecycleState==='ENABLED' || extension.lifecycleState==='DISABLED' || extension.lifecycleState==='INSTALLED'" class="link-button" (click)="rotateExtensionCredentials(extension)">Rotate credential</button><button *ngIf="extension.lifecycleState==='INSTALLED' || extension.lifecycleState==='DISABLED'" class="link-button" (click)="updateExtension(extension)">Update</button><button *ngIf="extension.lifecycleState==='INSTALLED' || extension.lifecycleState==='DISABLED'" class="link-button" (click)="rollbackExtension(extension)">Rollback</button><button class="link-button" (click)="checkExtensionHealth(extension)">Health</button><button *ngIf="extension.id==='observability.artio' && extension.lifecycleState==='ENABLED'" class="link-button" (click)="openObservability()">Open dashboards</button><button class="link-button" (click)="selectExtension(extension)">Configure</button><button class="link-button" (click)="loadExtensionAudit(extension)">Activity</button><button *ngIf="extension.lifecycleState!=='UNINSTALLED'" class="link-button danger" (click)="uninstallExtension(extension)">Uninstall</button></article></div><div *ngIf="extensionAuditFor" class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">EXTENSION ACTIVITY</p><h2>{{extensionAuditFor}}</h2></div><button class="link-button" (click)="extensionAuditFor=null;extensionAudit=[]">Close</button></div><p class="muted">Recent administrative lifecycle and invocation events. Secret values and request bodies are excluded.</p><table><thead><tr><th>TIME</th><th>ACTOR</th><th>ACTION</th><th>DETAILS</th></tr></thead><tbody><tr *ngFor="let event of extensionAudit"><td>{{event.occurredAt | date:"medium"}}</td><td>{{event.actorUserId}}</td><td>{{event.action}}</td><td>{{event.details | json}}</td></tr></tbody></table><p *ngIf="extensionAudit.length===0" class="empty">No activity recorded.</p></div><div *ngIf="selectedExtension?.lifecycleState==='ENABLED'" class="panel"><p class="eyebrow">LIVE DIAGNOSTIC</p><h2>Invoke extension</h2><p class="muted">This sends a real request to the enabled extension. Use a non-destructive operation and sample payload.</p><form class="create-form" (ngSubmit)="invokeExtension()"><select [(ngModel)]="extensionInvocation.extensionPoint" name="extensionPoint" required><option *ngFor="let point of selectedExtension.manifest.extensionPoints" [value]="point">{{point}}</option></select><input [(ngModel)]="extensionInvocation.operation" name="operation" placeholder="Operation" required><textarea [(ngModel)]="extensionInvocation.payloadJson" name="payload" rows="5" required></textarea><button class="primary">Send diagnostic request</button></form><pre *ngIf="extensionInvocationResult">{{extensionInvocationResult | json}}</pre></div><div *ngIf="selectedExtension" class="panel"><div class="panel-heading"><div><p class="eyebrow">EXTENSION SETTINGS</p><h2>{{selectedExtension.manifest.name}}</h2></div><button class="link-button" (click)="selectedExtension=null">Close</button></div><form class="create-form" (ngSubmit)="saveExtensionConfiguration()"><ng-container *ngFor="let field of extensionFields()"><div class="create-field"><span>{{field.value.label || field.key}}</span><small *ngIf="field.value.description">{{field.value.description}}</small><select *ngIf="field.value.type==='enum'" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key"><option *ngFor="let option of field.value.options" [value]="option">{{option}}</option></select><input *ngIf="field.value.type==='secret'" type="password" autocomplete="new-password" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key" [placeholder]="selectedExtension.configuredSecrets.includes(field.key) ? 'Configured — leave blank to keep existing value' : 'Secret value'" [required]="field.value.required && !selectedExtension.configuredSecrets.includes(field.key)"><input *ngIf="field.value.type==='text' || field.value.type==='number' || field.value.type==='url'" [type]="field.value.type==='number'?'number':'text'" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key" [required]="field.value.required"><textarea *ngIf="field.value.type==='json'" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key" rows="4" [required]="field.value.required"></textarea><label *ngIf="field.value.type==='boolean'"><input type="checkbox" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key"> Enabled</label></div></ng-container><button class="primary">Save configuration</button></form></div></section>
<section *ngIf="tab==='system'"><div class="panel"><p class="eyebrow">SYSTEM SETTINGS</p><h2>Installation configuration</h2><p class="muted">Changes are restricted to the system owner and recorded in the audit history.</p><form class="create-form" (ngSubmit)="saveSystemSettings()"><label>Store name<input [(ngModel)]="systemSettings.storeName" name="storeName" maxlength="120" required></label><div class="form-grid"><label>Country<artio-search-select [(ngModel)]="systemSettings.countryCode" name="countryCode" label="Store country" [options]="countryOptions"></artio-search-select></label><label>Currency<artio-search-select [(ngModel)]="systemSettings.currencyCode" name="currencyCode" label="Store currency" [options]="currencyOptions"></artio-search-select></label></div><div class="form-grid"><label>Default locale<artio-search-select [(ngModel)]="systemSettings.locale" name="locale" label="Store default locale" [options]="localeOptions"></artio-search-select></label><label>Time zone<artio-search-select [(ngModel)]="systemSettings.timezone" name="timezone" label="Store time zone" [options]="timezoneOptions"></artio-search-select></label></div><label>Supported languages<artio-search-select [(ngModel)]="systemSelectedLanguages" name="systemLanguages" label="Store content languages" [options]="storeLanguageOptions" [multiple]="true" placeholder="Choose languages"></artio-search-select><small>Comma-separated BCP 47 language tags.</small></label><label>External store URL<input [(ngModel)]="systemSettings.externalBaseUrl" name="externalBaseUrl" type="url" placeholder="https://shop.example.com"><small>HTTPS is required outside local development.</small></label><p class="muted">Distribution: {{systemSettings.distributionId}}</p><button class="primary">Save installation settings</button></form><button class="link-button" (click)="navigateTo('extensions')">Open Plugin Manager</button></div><div class="panel table-panel"><p class="eyebrow">REGIONAL PLUGIN PROVISIONING</p><h2>Recommended integrations</h2><p class="muted">Optional plugins are installed disabled. Enable them only after reviewing their settings. Missing releases stay unavailable until a trusted digest-pinned manifest is registered.</p><table><thead><tr><th>PLUGIN</th><th>STATUS</th><th>RECOMMENDATION</th></tr></thead><tbody><tr *ngFor="let item of distributionPlugins"><td>{{item.pluginId}}</td><td>{{item.status}}</td><td>{{item.reason}}</td></tr></tbody></table><p *ngIf="!distributionPlugins.length" class="empty">No regional plugin recommendations are configured.</p><button class="link-button" (click)="refreshDistributionPlugins()">Refresh provisioning status</button></div><div class="panel table-panel"><p class="eyebrow">SYSTEM SETTINGS AUDIT</p><h2>Recent changes</h2><table><thead><tr><th>TIME</th><th>ACTOR</th><th>METHOD</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let event of systemSettingsAudit"><td>{{event.occurredAt | date:"medium"}}</td><td>{{event.userId}}</td><td>{{event.action}} {{event.path}}</td><td>{{event.status}}</td></tr></tbody></table><p *ngIf="!systemSettingsAudit.length" class="empty">No settings changes recorded.</p></div></section><section *ngIf="tab==='pricing'"><div class="toolbar"><p>Manage selling prices by market and channel.</p><button class="primary" (click)="showPrice=!showPrice">＋ Add price</button></div><form *ngIf="showPrice" class="create-form" (ngSubmit)="createPrice()"><artio-sellable-select [(ngModel)]="priceDraft.sellableId" name="sellable" label="Priced product variant"></artio-sellable-select><input [(ngModel)]="priceDraft.amount" name="amount" type="number" placeholder="Amount" required><artio-search-select [(ngModel)]="priceDraft.currency" name="currency" label="Price currency" [options]="currencyOptions"></artio-search-select><input [(ngModel)]="priceDraft.market" name="market" placeholder="US" required><input [(ngModel)]="priceDraft.channel" name="channel" placeholder="WEB" required><label><input type="checkbox" [(ngModel)]="priceDraft.pricesIncludeTax" name="pricesIncludeTax"> Price includes tax</label><button class="primary">Save price</button></form><div class="panel table-panel"><table><thead><tr><th>SELLABLE</th><th>MARKET / CHANNEL</th><th>PRICE</th><th>TAX MODE</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let p of prices"><td>{{p.sellableId}}</td><td>{{p.market}} / {{p.channel}}</td><td>{{p.amount}} {{p.currency}}</td><td>{{p.pricesIncludeTax?'Tax inclusive':'Tax exclusive'}}</td><td>{{p.active?'Active':'Inactive'}}</td></tr></tbody></table></div></section>
<section *ngIf="tab==='pricing'"><div class="panel"><div class="panel-heading"><div><p class="eyebrow">TAX POLICY</p><h2>Sellable tax categories</h2></div></div><p class="muted">Assign categories using your merchant tax policy. Classification is not inferred from product text.</p><form class="create-form" (ngSubmit)="assignTaxCategory()"><artio-sellable-select [(ngModel)]="taxAssignment.sellableId" name="taxSellableId" label="Tax category product variant"></artio-sellable-select><select [(ngModel)]="taxAssignment.category" name="taxCategory"><option value="STANDARD">Standard</option><option value="REDUCED">Reduced</option><option value="ACCOMMODATION">Accommodation</option></select><button class="primary">Assign category</button></form><div class="table-panel" *ngIf="taxRules.length"><table><thead><tr><th>JURISDICTION</th><th>CATEGORY</th><th>RATE</th><th>VALID FROM</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let rule of taxRules"><td>{{rule.jurisdiction}}</td><td>{{rule.category}}</td><td>{{rule.percentage}}%</td><td>{{rule.validFrom}}</td><td>{{rule.active?'Active':'Inactive'}}</td></tr></tbody></table></div><div class="table-panel" *ngIf="sellableTaxCategories.length"><table><thead><tr><th>SELLABLE ID</th><th>ASSIGNED CATEGORY</th></tr></thead><tbody><tr *ngFor="let assignment of sellableTaxCategories"><td>{{assignment.sellableId}}</td><td>{{assignment.category}}</td></tr></tbody></table></div></div></section>
<section *ngIf="tab==='inventory' || tab==='orders'"><div class="panel"><p class="eyebrow">{{tab==='inventory'?'STOCK OPERATIONS':'FULFILMENT'}}</p><h2>{{tab==='inventory'?'Inventory overview':'Orders'}}</h2><p class="muted">{{tab==='inventory'?'Warehouse and stock balances are managed through the inventory API.':'Search, review and fulfil customer orders.'}}</p><form *ngIf="tab==='orders'" class="toolbar" (ngSubmit)="searchOrders()"><input [(ngModel)]="ordersQuery" name="orderQuery" maxlength="200" placeholder="Order ID, customer email or tracking"><select [(ngModel)]="ordersStatus" name="orderStatus"><option value="">All statuses</option><option *ngFor="let status of orderStatuses" [value]="status">{{status}}</option></select><button class="primary">Search</button><button type="button" class="link-button" (click)="exportOrders()">Export CSV</button></form><p class="muted" *ngIf="tab==='orders'">{{orderTotal}} orders · page {{orderPage+1}} of {{orderPages||1}}</p><div *ngFor="let order of orders" class="row"><span class="row-main"><strong>{{order.id}}</strong><small>{{order.status}} · {{order.createdAt | date:'medium'}} · {{order.customerEmail}} {{order.trackingNumber?'· '+order.trackingNumber:''}}</small></span><b>{{order.total}} {{order.currency}}</b><button *ngIf="tab==='orders'" class="link-button" (click)="viewOrder(order)">Details</button><button *ngIf="tab==='orders' && (order.status==='PAID' || order.status==='CONFIRMED')" class="link-button" (click)="shipOrder(order)">{{order.shippingMethodId?'Create label & ship':'Ship'}}</button><button *ngIf="tab==='orders' && order.shippingLabelAvailable" class="link-button" (click)="openShippingLabel(order)">Shipping label ↗</button><button *ngIf="tab==='orders' && order.status==='SHIPPED'" class="link-button" (click)="deliverOrder(order)">Mark delivered</button><button *ngIf="tab==='orders' && order.trackingNumber && order.status==='SHIPPED'" class="link-button" (click)="refreshOrderTracking(order)">Refresh tracking</button></div><p *ngIf="tab==='orders' && !orders.length" class="empty">No orders match these filters.</p><div class="toolbar" *ngIf="tab==='orders'"><button class="link-button" [disabled]="orderPage===0" (click)="loadOrders(orderPage-1)">← Previous</button><button class="link-button" [disabled]="orderPage+1>=orderPages" (click)="loadOrders(orderPage+1)">Next →</button></div><a class="link-button" href="/api/v1/warehouses" target="_blank" *ngIf="tab==='inventory'">Open warehouse API ↗</a></div><div *ngIf="selectedOrder" class="panel"><div class="panel-heading"><div><p class="eyebrow">ORDER DETAIL</p><h2>{{selectedOrder.id}}</h2></div><button class="link-button" (click)="selectedOrder=null">Close</button></div><p><strong>{{selectedOrder.status}}</strong> · {{selectedOrder.customerEmail}} · {{selectedOrder.createdAt | date:'medium'}}</p><p>Subtotal {{selectedOrder.subtotal}} + tax {{selectedOrder.tax}} + shipping {{selectedOrder.shipping}} = <strong>{{selectedOrder.total}} {{selectedOrder.currency}}</strong></p><p>Ship to: {{selectedOrder.shippingAddress}}</p><p>Bill to: {{selectedOrder.billingAddress}}</p><p *ngIf="selectedOrder.trackingNumber">Tracking: {{selectedOrder.trackingNumber}} · {{selectedOrder.shipmentReference}}</p><h3>Items</h3><div class="row" *ngFor="let line of selectedOrder.lines"><span>{{line.variantId}} {{line.bundleId?'· bundle '+line.bundleId:''}} · quantity {{line.quantity}}</span><b>{{line.unitPrice}} {{line.currency}}</b></div><h3>Shipments</h3><div class="row" *ngFor="let shipment of selectedShipments"><span>{{shipment.trackingNumber}} · {{shipment.items.length}} line(s)</span><small>{{shipment.orderStatus}}</small></div><form *ngIf="selectedOrder.status==='PAID' || selectedOrder.status==='CONFIRMED' || selectedOrder.status==='PARTIALLY_SHIPPED'" class="create-form" (ngSubmit)="createShipment()"><label>Tracking number<input [(ngModel)]="shipmentTrackingNumber" name="shipmentTracking" maxlength="255" required></label><div class="row" *ngFor="let line of selectedOrder.lines"><span class="row-main">{{line.variantId}} · {{line.shippedQuantity}} of {{line.quantity}} shipped</span><label>Ship now<input type="number" min="0" step="0.0001" [max]="line.quantity-line.shippedQuantity" [(ngModel)]="line.shipQuantity" [name]="'ship-'+line.id"></label></div><button class="primary" [disabled]="!shipmentTrackingNumber.trim()">Create shipment</button></form><h3>Payments</h3><div class="row" *ngFor="let payment of selectedOrder.payments"><span>{{payment.method}} · {{payment.status}} · {{payment.providerReference}} · refunded {{payment.refundedAmount}} {{payment.currency}}</span><b>{{payment.amount}} {{payment.currency}}</b><button *ngIf="payment.status==='CAPTURED' || payment.status==='PARTIALLY_REFUNDED'" class="link-button" (click)="refundPayment(payment)">Refund</button></div><h3>Returns</h3><div class="row" *ngFor="let item of selectedReturns"><span class="row-main"><strong>{{item.status}}</strong><small>{{item.reason}} · {{item.createdAt | date:'medium'}} · <span *ngFor="let line of item.items">{{line.quantity}} × {{line.orderItemId}} </span></small><small *ngIf="item.staffNote">Staff note: {{item.staffNote}}</small></span><button *ngIf="item.status==='REQUESTED'" class="link-button" (click)="reviewReturn(item,true)">Approve</button><button *ngIf="item.status==='REQUESTED'" class="link-button" (click)="reviewReturn(item,false)">Reject</button><ng-container *ngIf="item.status==='APPROVED'"><label *ngIf="orderWarehouses.length">Restock warehouse<artio-search-select [(ngModel)]="item.receiveWarehouseId" [name]="'return-warehouse-'+item.id" [options]="warehouseOptions" label="Restocking warehouse" placeholder="No restocking"></artio-search-select></label><button *ngIf="orderWarehouses.length" class="link-button" [disabled]="!item.receiveWarehouseId" (click)="receiveReturn(item,true)">Receive &amp; restock</button><button class="link-button" (click)="receiveReturn(item,false)">Receive without restocking</button></ng-container></div><p *ngIf="!selectedReturns.length" class="muted">No return requests for this order.</p><pre>{{selectedOrder.taxSnapshot | json}}</pre><h3>Timeline & staff notes</h3><div class="row" *ngFor="let event of selectedTimeline"><span class="row-main"><strong>{{event.eventType}}</strong><small>{{event.message}} · {{event.occurredAt | date:'medium'}}</small></span><span class="muted">{{event.customerVisible?'Customer visible':'Internal'}}</span></div><form class="toolbar" (ngSubmit)="addOrderNote()"><input [(ngModel)]="orderNote" name="orderNote" maxlength="2000" placeholder="Internal staff note"><button class="primary" [disabled]="!orderNote.trim()">Add note</button></form></div></section>
<artio-product-media-admin *ngIf="mediaProduct" [productId]="mediaProduct.id" [productName]="mediaProduct.name" (close)="mediaProduct=null"></artio-product-media-admin><artio-catalog-metadata-admin *ngIf="tab==='catalogData'"></artio-catalog-metadata-admin><artio-inventory-admin *ngIf="tab==='inventory'"></artio-inventory-admin><artio-gift-card-admin *ngIf="tab==='giftCards'"></artio-gift-card-admin><section *ngIf="tab==='operations'"><div class="panel"><div class="panel-heading"><div><p class="eyebrow">DELIVERY HEALTH</p><h2>Outbox queues</h2></div><button class="link-button" (click)="loadOutbox()">Refresh</button></div><div class="metrics" *ngIf="outboxDiagnostics"><article><span>Pending events</span><strong>{{outboxDiagnostics.eventPending}}</strong><small>{{outboxDiagnostics.eventStaleClaims}} stale claims</small></article><article><span>Dead events</span><strong>{{outboxDiagnostics.eventDead}}</strong><small>Review and replay below</small></article><article><span>Pending email</span><strong>{{outboxDiagnostics.emailPending}}</strong><small>{{outboxDiagnostics.emailStaleClaims}} stale claims</small></article><article><span>Dead email</span><strong>{{outboxDiagnostics.emailDead}}</strong><small>Requires operator review</small></article><article><span>Webhook receipts</span><strong>{{outboxDiagnostics.webhookUnprocessed}}</strong><small>{{outboxDiagnostics.webhookOlderThanRetention}} past retention</small></article></div><div class="panel table-panel" *ngIf="outboxDeadEvents.length"><h3>Dead-letter events</h3><table><thead><tr><th>TYPE</th><th>AGGREGATE</th><th>ATTEMPTS</th><th>ERROR CLASS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let event of outboxDeadEvents"><td>{{event.eventType}}</td><td>{{event.aggregateId}}</td><td>{{event.attempts}}</td><td>{{event.errorClass}}</td><td><button class="link-button" (click)="replayOutboxEvent(event)">Replay</button></td></tr></tbody></table></div><div class="panel"><div class="panel-heading"><div><p class="eyebrow">KAFKA</p><h2>Consumer health</h2></div></div><p *ngIf="kafkaConsumerLag">{{kafkaConsumerLag.group}} · {{kafkaConsumerLag.topic}} · {{kafkaConsumerLag.totalLag}} messages behind</p><table *ngIf="kafkaConsumerLag.partitions.length"><thead><tr><th>PARTITION</th><th>COMMITTED</th><th>END</th><th>LAG</th></tr></thead><tbody><tr *ngFor="let partition of kafkaConsumerLag.partitions"><td>{{partition.partition}}</td><td>{{partition.committedOffset}}</td><td>{{partition.endOffset}}</td><td>{{partition.lag}}</td></tr></tbody></table><p *ngIf="!kafkaConsumerLag" class="empty">Consumer lag unavailable; verify Kafka broker and topic.</p><div class="metrics"><article><span>Dead letters</span><strong>{{kafkaDeadLetters.dead}}</strong></article><article><span>Replay pending</span><strong>{{kafkaDeadLetters.replayPending}}</strong></article><article><span>Replayed</span><strong>{{kafkaDeadLetters.replayed}}</strong></article></div><div class="panel table-panel" *ngIf="kafkaDeadLetterItems.length"><h3>Kafka consumer dead letters</h3><table><thead><tr><th>EVENT</th><th>SOURCE</th><th>OFFSET</th><th>FAILURE</th><th>ATTEMPTS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let event of kafkaDeadLetterItems"><td>{{event.eventType||event.eventId||'Unknown event'}}</td><td>{{event.sourceTopic}} / {{event.partition}}</td><td>{{event.offset}}</td><td>{{event.errorClass}}</td><td>{{event.replayAttempts}}</td><td><button class="link-button" *ngIf="event.status==='DEAD'" (click)="replayKafkaDeadLetter(event)">Replay</button><span *ngIf="event.status!=='DEAD'">{{event.status}}</span></td></tr></tbody></table></div></div><p *ngIf="!outboxDiagnostics" class="empty">Loading delivery diagnostics…</p></div></section><section *ngIf="tab==='users'"><div class="toolbar"><label class="search">⌕ <input [(ngModel)]="usersQuery" (ngModelChange)="loadUsers()" placeholder="Search name or email"></label><select [(ngModel)]="usersActivity" (ngModelChange)="loadUsers()"><option value="ALL">All activity</option><option value="RECENT">Signed in within 30 days</option><option value="STALE">No sign-in in 30+ days</option><option value="NEVER">Never signed in</option></select></div><div class="panel table-panel"><table><thead><tr><th>CUSTOMER</th><th>ROLE</th><th>VERIFIED</th><th>STATUS</th><th>LAST SIGN-IN</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let user of users"><td><strong>{{user.firstName}} {{user.lastName}}</strong><small>{{user.email}}</small></td><td>{{user.role}}</td><td>{{user.emailVerified?'Yes':'No'}}</td><td>{{user.active?'Active':'Disabled'}}</td><td>{{user.lastLogin?(user.lastLogin | date:'medium'):'Never'}}</td><td><button class="link-button" (click)="setUserActive(user)">{{user.active?'Disable':'Enable'}}</button><button class="link-button" *ngIf="!user.emailVerified" (click)="verifyUser(user)">Verify email</button><button class="link-button" (click)="viewLoyalty(user)">Loyalty</button></td></tr></tbody></table></div><div *ngIf="selectedLoyalty" class="panel"><div class="panel-heading"><div><p class="eyebrow">LOYALTY ACCOUNT</p><h2>{{selectedLoyalty.user.firstName}} {{selectedLoyalty.user.lastName}}</h2></div><button class="link-button" (click)="selectedLoyalty=null">Close</button></div><p>{{selectedLoyalty.account.balance.points}} points · {{selectedLoyalty.account.balance.tier}}</p><button class="primary" (click)="adjustLoyalty()">Adjust points</button><div class="row" *ngFor="let transaction of selectedLoyalty.account.transactions"><span>{{transaction.kind}} · {{transaction.orderId||transaction.refundId||'manual'}}</span><b>{{transaction.points}}</b></div></div></section><p class="error" *ngIf="error">{{error}}</p><p class="notice" role="status" *ngIf="success">{{success}}</p></main></div>`})
export class AdminComponent {
 distributionPlugins:any[]=[];extensionCatalog:any[]=[];
 systemSettings:any={storeName:"Artio Store",countryCode:"CH",currencyCode:"CHF",locale:"de-CH",timezone:"Europe/Zurich",externalBaseUrl:"",distributionId:"switzerland-v1"};systemLanguages="de,fr,it,en";systemSelectedLanguages=["de","fr","it","en"];storeLanguageOptions=LANGUAGE_OPTIONS;countryOptions=COUNTRY_OPTIONS;currencyOptions=CURRENCY_OPTIONS;localeOptions=LOCALE_OPTIONS;timezoneOptions=TIMEZONE_OPTIONS;systemSettingsAudit:any[]=[];outboxDiagnostics:any=null;outboxDeadEvents:any[]=[];kafkaDeadLetters:any={dead:0,replayPending:0,replayed:0};kafkaDeadLetterItems:any[]=[];kafkaConsumerLag:any=null;setupChecked=false;setupRequired=false;developerMode=false;
 bundleTranslationBundle:any=null;bundleTranslationLocale='de';bundleTranslationDraft:any={name:'',optionGroupNames:{}};
 productImportReport:any=null;mediaProduct:Product|null=null;private router=inject(Router);today=new Date();success='';navOpen=false;overviewProducts:Product[]=[];overviewProductTotal=0;overviewOrderTotal=0;private http=inject(HttpClient); token=localStorage.getItem('artio-admin-token'); email=localStorage.getItem('artio-admin-email')??'';password='';error='';extensionHealth='';searchIndexStatus='';tab='overview';query='';products:Product[]=[];catalogPage=0;catalogSize=25;catalogTotal=0;catalogState='ALL';catalogSort='updatedAt';catalogDirection='desc';catalogBrandId='';catalogCategoryId='';catalogBrands:any[]=[];catalogCategories:any[]=[];bundles:any[]=[];extensions:any[]=[];extensionAudit:any[]=[];extensionAuditFor:string|null=null;extensionInvocation={extensionPoint:'',operation:'health',payloadJson:'{}'};extensionInvocationResult:any=null;selectedExtension:any=null;extensionConfig:Record<string,any>={};extensionManifestJson='';prices:any[]=[];taxRules:any[]=[];sellableTaxCategories:any[]=[];taxAssignment={sellableId:'',category:'STANDARD'};orders:any[]=[];orderPage=0;orderSize=25;orderTotal=0;orderPages=0;ordersQuery='';ordersStatus='';orderStatuses=['PENDING','CONFIRMED','PAID','PARTIALLY_SHIPPED','SHIPPED','DELIVERED','CANCELLED','RETURNED'];selectedOrder:any=null;selectedReturns:any[]=[];orderWarehouses:any[]=[];selectedTimeline:any[]=[];orderNote='';selectedLoyalty:any=null;users:any[]=[];usersQuery='';usersActivity='ALL';showBundle=false;showExtensionRegistration=false;showPrice=false;translationProduct:Product|null=null;translationLocale='de';translationDraft={name:'',description:'',seoSlug:'',seoTitle:'',seoDescription:''};bundleDraft:any={name:'',sku:'',type:'CONFIGURABLE',sellables:''};priceDraft:any={sellableId:'',amount:0,currency:'USD',market:'US',channel:'WEB',pricesIncludeTax:false};
 selectedShipments:any[]=[];shipmentTrackingNumber='';mfaCode='';mfaSetupRequired=false;mfaEnrollment:any=null;mfaQrCode='';mfaCopied=false;mfaBackupCodes:string[]=[];
 get isSuperadmin():boolean{try{const payload=JSON.parse(atob((this.token??"").split(".")[1].replace(/-/g,"+").replace(/_/g,"/")));return payload.role==="SUPERADMIN"}catch{return false}} get title():string{return ({system:"System Settings",overview:'Overview',products:'Products',productNew:'New product',catalogData:'Catalog data',bundles:'Bundles',extensions:'Extensions',pricing:'Pricing',inventory:'Inventory',orders:'Orders',users:'Customers',giftCards:'Gift cards',operations:'Operations'} as Record<string,string>)[this.tab]??'Overview'}
 navigateTo(tab:string):void{this.navOpen=false;this.router.navigateByUrl(tab==='productNew'?'/products/new':'/'+tab)}
 private syncRoute():void{const path=this.router.url.split('?')[0];const tab=path==='/products/new'?'productNew':path.slice(1);if(['overview','products','productNew','catalogData','bundles','extensions','pricing','inventory','orders','users','giftCards','operations','system'].includes(tab))this.tab=tab;this.error='';this.success='';if(this.token&&!this.mfaSetupRequired){switch(this.tab){case 'overview':this.loadDashboard();break;case 'products':this.loadProducts();break;case 'bundles':this.loadBundles();break;case 'extensions':this.loadExtensions();break;case 'pricing':this.loadPrices();break;case 'orders':this.loadOrders();break;case 'users':this.loadUsers();break;case 'operations':this.loadOutbox();break;case 'system':if(this.isSuperadmin)this.loadSystemSettings();break;}}}
 productCreated(id:string):void{this.loadCatalogFilters();this.catalogPage=0;this.catalogState='ALL';this.query='';this.catalogBrandId='';this.catalogCategoryId='';this.router.navigateByUrl('/products').then(()=>this.success='Product created successfully. Add pricing and stock when you are ready to sell.')}
 get filteredProducts():Product[]{return this.products} get catalogPages():number{return Math.max(1,Math.ceil(this.catalogTotal/this.catalogSize))}
 resetCatalogPage():void{this.catalogPage=0;this.loadProducts()} previousCatalogPage():void{if(this.catalogPage>0){this.catalogPage--;this.loadProducts()}} nextCatalogPage():void{if(this.catalogPage+1<this.catalogPages){this.catalogPage++;this.loadProducts()}}
 extensionFields():Array<{key:string;value:any}>{return Object.entries(this.selectedExtension?.manifest.configuration??{}).map(([key,value])=>({key,value}))}
 constructor(){this.syncRoute();this.router.events.pipe(takeUntilDestroyed()).subscribe(event=>{if(event instanceof NavigationEnd)this.syncRoute()});this.loadSetupStatus();if(this.token&&!this.isMfaSetupOnlyToken()){this.loadCatalogFilters();this.loadDashboard();this.loadProducts();this.loadBundles();this.loadOrders();this.loadPrices();}}
 private isMfaSetupOnlyToken():boolean{try{if(!this.token)return false;const payload=this.token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');return JSON.parse(atob(payload)).mfaSetupOnly===true}catch{return false}}
 loadSetupStatus():void{this.http.get<any>('/api/v1/setup/status').subscribe({next:r=>{this.setupChecked=true;this.setupRequired=!!r.required;this.developerMode=!!r.developerMode;if(this.developerMode){if(this.isMfaSetupOnlyToken()){localStorage.removeItem('artio-admin-token');this.token=null;this.mfaSetupRequired=false;this.mfaEnrollment=null;this.mfaQrCode=''}if(!this.token){this.email='admin@example.test';this.password='ArtioLocalAdmin!2026';this.mfaCode=''}}},error:()=>{this.setupChecked=true;this.error='Could not check first-run setup status.'}})}
 setupFinished(result:{email:string;demoCredentials:boolean}):void{this.setupRequired=false;this.email=result.email;this.password=result.demoCredentials?'ArtioLocalAdmin!2026':'';this.mfaCode='';this.error=''}
 login():void{this.http.post<any>('/api/v1/auth/login',{email:this.email,password:this.password,mfaCode:this.mfaCode||null}).subscribe({next:r=>{if(r.role==='CUSTOMER'){this.error='Administrator access is required.';return;}this.token=r.accessToken;localStorage.setItem('artio-admin-token',r.accessToken);localStorage.setItem('artio-admin-email',this.email);if(r.mfaEnrollmentRequired){this.mfaSetupRequired=true;this.beginMfaEnrollment();return;}this.mfaSetupRequired=false;this.loadCatalogFilters();this.loadDashboard();this.loadProducts();this.loadBundles();this.loadOrders();this.loadPrices();},error:e=>this.error=e.error?.message??'Unable to sign in. Check your credentials and administrator role.'})}
 beginMfaEnrollment():void{this.mfaCode='';this.mfaCopied=false;this.mfaQrCode='';this.http.post<any>('/api/v1/auth/mfa/totp/enrollment',{}).subscribe({next:r=>{this.mfaEnrollment=r;this.error='';QRCode.toDataURL(r.otpauthUri,{errorCorrectionLevel:'M',margin:2,width:224,color:{dark:'#0F172A',light:'#FFFFFF'}}).then(uri=>this.mfaQrCode=uri).catch(()=>this.error='Could not generate the setup QR code. Use the manual setup key below.')},error:e=>this.error=e.error?.message??'Could not start authenticator enrollment.'})}
 async copyMfaSecret():Promise<void>{try{await navigator.clipboard.writeText(this.mfaEnrollment.base32Secret);this.mfaCopied=true}catch{this.error='Clipboard access is unavailable. Select and copy the setup key manually.'}}
 verifyMfaEnrollment():void{this.http.post<any>('/api/v1/auth/mfa/totp/verify',{code:this.mfaCode}).subscribe({next:r=>{this.mfaBackupCodes=r.backupCodes??[];this.mfaCode='';this.error=''},error:e=>{const message=e.error?.message??'';this.error=message.toLowerCase().includes('totp')?'That code is invalid or expired. Enter the newest six-digit code from your authenticator app.':message||'Enter a current authenticator code.'}})}
 finishMfaSetup():void{localStorage.removeItem('artio-admin-token');this.token=null;this.mfaSetupRequired=false;this.mfaEnrollment=null;this.mfaBackupCodes=[];this.password='';this.mfaCode='';this.error='Authenticator protection is active. Sign in again with a current code.'}
 logout():void{localStorage.removeItem('artio-admin-token');localStorage.removeItem('artio-admin-email');this.token=null}
 get catalogBrandOptions():SelectOption[]{return [{value:'',label:'All brands'},...this.catalogBrands.map(x=>({value:x.id,label:x.name}))]}
 get catalogCategoryOptions():SelectOption[]{return [{value:'',label:'All categories'},...this.catalogCategories.map(x=>({value:x.id,label:x.name}))]}
 bundleSellables:string[]=[];
 get warehouseOptions():SelectOption[]{return [{value:'',label:'No restocking'},...this.orderWarehouses.map(x=>({value:x.id,label:x.name,detail:x.code}))]}
 loadDashboard():void{this.http.get<{items:Product[];total:number}>('/api/v1/admin/catalog/products?page=0&size=5&state=ALL&sort=updatedAt&direction=desc').subscribe({next:r=>{this.overviewProducts=r.items;this.overviewProductTotal=r.total},error:e=>this.error=e.error?.message??'Could not load catalog summary.'});this.http.get<{totalElements:number}>('/api/v1/admin/orders?page=0&size=1&sort=createdAt&direction=desc').subscribe({next:r=>this.overviewOrderTotal=r.totalElements,error:()=>undefined})}
 loadCatalogFilters():void{this.http.get<any[]>('/api/v1/brands').subscribe({next:rows=>this.catalogBrands=rows,error:()=>undefined});this.http.get<any[]>('/api/v1/categories').subscribe({next:rows=>this.catalogCategories=rows,error:()=>undefined})}
 loadProducts():void{const params=new URLSearchParams({page:String(this.catalogPage),size:String(this.catalogSize),state:this.catalogState,sort:this.catalogSort,direction:this.catalogDirection});if(this.query.trim())params.set('q',this.query.trim());if(this.catalogBrandId)params.set('brandId',this.catalogBrandId);if(this.catalogCategoryId)params.set('categoryId',this.catalogCategoryId);this.http.get<{items:Product[];total:number}>(`/api/v1/admin/catalog/products?${params}`).subscribe({next:r=>{this.products=r.items;this.catalogTotal=r.total;for(const p of this.products)this.http.get<Array<{id:string;name:string;sku:string;active:boolean}>>(`/api/v1/products/${p.id}/variants`).subscribe({next:v=>p.variants=v,error:()=>p.variants=[]})},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load products.'})}
 loadBundles():void{this.http.get<any[]>('/api/v1/bundles').subscribe({next:r=>this.bundles=r,error:()=>undefined})}
 loadExtensions():void{this.http.get<any[]>('/api/v1/admin/extensions').subscribe({next:r=>this.extensions=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load extensions.'});this.http.get<any[]>('/api/v1/admin/extensions/catalog').subscribe({next:r=>this.extensionCatalog=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load plugin catalog.'})}
 selectCatalogPlugin(item:any):void{const plugin=this.extensions.find(candidate=>candidate.id===item.pluginId);if(plugin)this.selectExtension(plugin)}
 restoreCatalogPlugin(item:any):void{this.http.post(`/api/v1/admin/extensions/${item.pluginId}/restore`,{}).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.message??'Could not restore the plugin registration.'})}
 invokeExtension():void{if(!this.selectedExtension)return;let payload:any;try{payload=JSON.parse(this.extensionInvocation.payloadJson)}catch{this.error='Diagnostic payload must be valid JSON.';return}const body={...this.extensionInvocation,payload,idempotencyKey:crypto.randomUUID(),deadlineMillis:5000};this.http.post<any>('/api/v1/admin/extensions/'+this.selectedExtension.manifest.id+'/invoke',body).subscribe({next:r=>{this.extensionInvocationResult=r;this.error=''},error:e=>{this.extensionInvocationResult=null;this.error=e.error?.message??e.error?.detail??e.error?.message??'Extension diagnostic request failed.'}})}
 loadExtensionAudit(extension:any):void{this.extensionAuditFor=extension.id;this.http.get<any[]>('/api/v1/admin/extensions/'+extension.id+'/audit').subscribe({next:r=>this.extensionAudit=r,error:e=>{this.extensionAudit=[];this.error=e.error?.message??e.error?.detail??'Could not load extension activity.'}})}
 rebuildSearchIndex():void{this.searchIndexStatus='Rebuilding search documents…';this.http.post<{productsIndexed:number;translationsIndexed:number}>('/api/v1/admin/catalog/search-index/rebuild',{}).subscribe({next:r=>this.searchIndexStatus=`Indexed ${r.productsIndexed} products and ${r.translationsIndexed} translations.`,error:e=>this.searchIndexStatus=e.error?.message??e.error?.detail??'Search index rebuild failed.'})}
 loadPrices():void{this.http.get<any[]>('/api/v1/prices').subscribe({next:r=>this.prices=r,error:()=>undefined});this.http.get<any[]>('/api/v1/tax-rules').subscribe({next:r=>this.taxRules=r,error:()=>undefined});this.http.get<any[]>('/api/v1/tax-rules/sellables/categories').subscribe({next:r=>this.sellableTaxCategories=r,error:()=>undefined})}
 loadOrders(page=this.orderPage):void{this.orderPage=page;const params=new URLSearchParams({page:String(page),size:String(this.orderSize),sort:'createdAt',direction:'desc'});if(this.ordersStatus)params.set('status',this.ordersStatus);if(this.ordersQuery.trim())params.set('q',this.ordersQuery.trim());this.http.get<any>('/api/v1/admin/orders?'+params.toString()).subscribe({next:r=>{this.orders=r.items;this.orderTotal=r.totalElements;this.orderPages=r.totalPages},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load orders.'})}
 searchOrders():void{this.loadOrders(0)}
 viewOrder(order:any):void{this.http.get<any>('/api/v1/admin/orders/'+order.id).subscribe({next:r=>{this.selectedOrder=r;for(const line of r.lines??[])line.shipQuantity=0;this.shipmentTrackingNumber='';this.http.get<any[]>('/api/v1/admin/orders/'+order.id+'/shipments').subscribe({next:shipments=>this.selectedShipments=shipments,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load shipments.'});this.http.get<any[]>('/api/v1/admin/orders/'+order.id+'/returns').subscribe({next:returns=>this.selectedReturns=returns,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load order returns.'});this.http.get<any[]>('/api/v1/warehouses').subscribe({next:warehouses=>{this.orderWarehouses=warehouses.filter(w=>w.active)},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load warehouses.'});this.loadOrderTimeline(order.id)},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load order details.'})}
 createShipment():void{if(!this.selectedOrder)return;const items=(this.selectedOrder.lines??[]).filter((line:any)=>Number(line.shipQuantity)>0).map((line:any)=>({orderItemId:line.id,quantity:Number(line.shipQuantity)}));if(!this.shipmentTrackingNumber.trim()||items.length===0){this.error='Enter a tracking number and a quantity for at least one order line.';return}this.http.post<any>(`/api/v1/admin/orders/${this.selectedOrder.id}/shipments`,{trackingNumber:this.shipmentTrackingNumber.trim(),items}).subscribe({next:()=>{this.error='';this.viewOrder({id:this.selectedOrder.id});this.loadOrders()},error:e=>this.error=e.error?.message??e.error?.detail??e.error?.message??'Could not create shipment.'})}
 loadOrderTimeline(orderId:string):void{this.http.get<any[]>('/api/v1/admin/orders/'+orderId+'/timeline').subscribe({next:events=>this.selectedTimeline=events,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load order timeline.'})}
 addOrderNote():void{if(!this.selectedOrder||!this.orderNote.trim())return;this.http.post<any>(`/api/v1/admin/orders/${this.selectedOrder.id}/notes`,{message:this.orderNote.trim()}).subscribe({next:()=>{this.orderNote='';this.loadOrderTimeline(this.selectedOrder.id)},error:e=>this.error=e.error?.message??e.error?.detail??'Could not add staff note.'})}
 reviewReturn(item:any,approve:boolean):void{const note=prompt(approve?'Optional approval note':'Reason for rejecting this return');if(note===null)return;this.http.post<any>(`/api/v1/admin/orders/${item.orderId}/returns/${item.id}/review`,{approve,note}).subscribe({next:()=>this.viewOrder({id:item.orderId}),error:e=>this.error=e.error?.message??e.error?.detail??'Could not review return.'})}
 receiveReturn(item:any,restock:boolean):void{if(!this.selectedOrder)return;let note=prompt(restock?'Optional receiving note':'Optional note');if(note===null)return;const warehouseId=restock?item.receiveWarehouseId:null;if(restock&&!warehouseId){this.error='Choose a warehouse before restocking.';return}this.http.post<any>(`/api/v1/admin/orders/${item.orderId}/returns/${item.id}/receive`,{restock,warehouseId,note}).subscribe({next:()=>this.viewOrder({id:this.selectedOrder.id}),error:e=>this.error=e.error?.message??e.error?.detail??'Could not receive return.'})}
 refundPayment(payment:any):void{const amount=prompt('Refund amount in '+payment.currency+'. Leave empty to refund the remaining amount.');if(amount===null)return;const normalized=amount.trim();const numeric=normalized?Number(normalized):null;if(numeric!==null&&(!Number.isFinite(numeric)||numeric<=0)){this.error='Enter a positive refund amount.';return}const summary=numeric===null?'the remaining balance':numeric+' '+payment.currency;if(!window.confirm('Confirm refund of '+summary+'? This sends a real refund request to the payment provider.'))return;const storageKey='artio-refund-key:'+payment.id+':'+(normalized||'remaining');let idempotencyKey=sessionStorage.getItem(storageKey);if(!idempotencyKey){idempotencyKey=crypto.randomUUID();sessionStorage.setItem(storageKey,idempotencyKey)}const body={amount:numeric};this.http.post<any>('/api/v1/payments/'+payment.id+'/refund',body,{headers:{'Idempotency-Key':idempotencyKey}}).subscribe({next:()=>{sessionStorage.removeItem(storageKey);if(this.selectedOrder)this.viewOrder({id:this.selectedOrder.id})},error:e=>this.error=e.error?.message??e.error?.detail??'Refund was not confirmed. Retry with the same amount.'})}
 exportOrders():void{const params=new URLSearchParams();if(this.ordersStatus)params.set('status',this.ordersStatus);if(this.ordersQuery.trim())params.set('q',this.ordersQuery.trim());this.http.get('/api/v1/admin/orders/export.csv?'+params.toString(),{responseType:'blob'}).subscribe({next:blob=>{const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='artio-orders.csv';link.click();URL.revokeObjectURL(url)},error:e=>this.error=e.error?.message??e.error?.detail??'Could not export orders.'})}
 loadOutbox():void{this.http.get<any>('/api/v1/admin/operations/outbox').subscribe({next:r=>this.outboxDiagnostics=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load delivery diagnostics.'});this.http.get<any[]>('/api/v1/admin/operations/outbox/events/dead').subscribe({next:r=>this.outboxDeadEvents=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load dead-letter events.'});this.loadKafkaOperations()}
 loadKafkaOperations():void{this.http.get<any>('/api/v1/admin/operations/kafka/dead-letters').subscribe({next:r=>this.kafkaDeadLetters=r,error:()=>undefined});this.http.get<any[]>('/api/v1/admin/operations/kafka/dead-letters/items').subscribe({next:r=>this.kafkaDeadLetterItems=r,error:()=>undefined});this.http.get<any>('/api/v1/admin/operations/kafka/consumer-lag').subscribe({next:r=>this.kafkaConsumerLag=r,error:()=>this.kafkaConsumerLag=null})}
 replayKafkaDeadLetter(event:any):void{if(!window.confirm('Replay Kafka event '+(event.eventId??event.id)+'? Consumer inbox deduplicates stable event IDs.'))return;this.http.post('/api/v1/admin/operations/kafka/dead-letters/'+event.id+'/replay',{}).subscribe({next:()=>this.loadKafkaOperations(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not replay this Kafka event.'})}
 replayOutboxEvent(event:any):void{if(!window.confirm('Replay event '+event.id+'? Consumers must deduplicate this stable event ID.'))return;this.http.post('/api/v1/admin/operations/outbox/events/'+event.id+'/replay',{}).subscribe({next:()=>this.loadOutbox(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not replay this event.'})}
 loadSystemSettings():void{this.http.get<any>('/api/v1/admin/system/settings').subscribe({next:r=>{this.systemSettings=r;this.systemLanguages=(r.availableLanguages??[]).join(',');this.systemSelectedLanguages=[...(r.availableLanguages??[])]},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load system settings.'});this.http.get<any[]>('/api/v1/admin/system/settings/audit').subscribe({next:r=>this.systemSettingsAudit=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load system settings audit.'});this.loadDistributionPlugins()}
 loadDistributionPlugins():void{this.http.get<any[]>('/api/v1/admin/system/distribution/plugins').subscribe({next:r=>this.distributionPlugins=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load regional plugin status.'})}
 refreshDistributionPlugins():void{this.http.post<any[]>('/api/v1/admin/system/distribution/plugins/refresh',{}).subscribe({next:r=>this.distributionPlugins=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not refresh regional plugin status.'})}
 saveSystemSettings():void{if(!this.systemSelectedLanguages.length){this.error='Choose at least one content language.';return;}const request={...this.systemSettings,availableLanguages:this.systemSelectedLanguages};this.http.put<any>('/api/v1/admin/system/settings',request).subscribe({next:r=>{this.systemSettings=r;this.systemLanguages=r.availableLanguages.join(',');this.error='';this.loadSystemSettings()},error:e=>this.error=e.error?.message??e.error?.detail??'Could not save system settings.'})}
 loadUsers():void{const params=new URLSearchParams({limit:'100',offset:'0',activity:this.usersActivity});if(this.usersQuery.trim())params.set('q',this.usersQuery.trim());this.http.get<any[]>('/api/v1/admin/users?'+params.toString()).subscribe({next:r=>this.users=r,error:e=>this.error=e.error?.message??e.error?.detail??'Could not load customers.'})}
 shipOrder(order:any):void{const trackingNumber=order.shippingMethodId?null:prompt('Tracking number');if(!order.shippingMethodId&&!trackingNumber)return;this.http.post(`/api/v1/admin/orders/${order.id}/ship`,{trackingNumber}).subscribe({next:()=>this.loadOrders(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not ship this order.'})}
 openShippingLabel(order:any):void{const popup=window.open('about:blank','_blank');if(!popup){this.error='Allow pop-ups to open the shipping label.';return}popup.opener=null;this.http.get(`/api/v1/admin/orders/${order.id}/label`,{responseType:'blob'}).subscribe({next:blob=>{const url=URL.createObjectURL(blob);popup.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60_000)},error:e=>{popup.close();this.error=e.error?.message??e.error?.detail??'Could not load the shipping label.'}})}
 deliverOrder(order:any):void{this.http.post(`/api/v1/admin/orders/${order.id}/deliver`,{}).subscribe({next:()=>this.loadOrders(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not update this order.'})}
 refreshOrderTracking(order:any):void{this.http.post<any>(`/api/v1/admin/orders/${order.id}/tracking/refresh`,{}).subscribe({next:r=>{this.error='Carrier update: '+r.status+(r.lastLocation?' · '+r.lastLocation:'');this.loadOrders();if(this.selectedOrder?.id===order.id)this.viewOrder(order)},error:e=>this.error=e.error?.message??e.error?.detail??'Carrier tracking is not available for this shipping provider.'})}
 setUserActive(user:any):void{this.http.put('/api/v1/admin/users/'+user.id+'/active',{active:!user.active}).subscribe(()=>this.loadUsers())}
 verifyUser(user:any):void{this.http.put('/api/v1/admin/users/'+user.id+'/email-verification',{verified:true}).subscribe(()=>this.loadUsers())}
 viewLoyalty(user:any):void{this.http.get<any>(`/api/v1/admin/loyalty/${user.id}`).subscribe({next:account=>this.selectedLoyalty={user,account},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load loyalty account.'})}
 adjustLoyalty():void{if(!this.selectedLoyalty)return;const points=Number(prompt('Points adjustment. Use a negative number to remove points.'));if(!Number.isInteger(points)||points===0||Math.abs(points)>1000000){this.error='Enter a whole point adjustment between -1,000,000 and 1,000,000.';return}const reason=prompt('Reason for this audited adjustment');if(!reason?.trim())return;if(!window.confirm(`Apply ${points>0?'+':''}${points} points?`))return;const user=this.selectedLoyalty.user;const storageKey=`artio-loyalty-adjust:${user.id}:${points}`;let key=sessionStorage.getItem(storageKey);if(!key){key=crypto.randomUUID();sessionStorage.setItem(storageKey,key)}this.http.post<any>(`/api/v1/admin/loyalty/${user.id}/adjust`,{points,reason:reason.trim()},{headers:{'Idempotency-Key':key}}).subscribe({next:account=>{sessionStorage.removeItem(storageKey);this.selectedLoyalty={user,account}},error:e=>this.error=e.error?.message??e.error?.detail??'Could not adjust loyalty points.'})}
 exportProducts():void{this.http.get('/api/v1/admin/catalog/products/export',{responseType:'blob'}).subscribe({next:blob=>{const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='artio-products.csv';anchor.click();URL.revokeObjectURL(url);this.error=''},error:e=>this.error=e.error?.message??e.error?.detail??'Could not export products.'})}
 importProducts(event:Event):void{const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;if(!file.name.toLowerCase().endsWith('.csv')){this.error='Choose a .csv file.';return}const form=new FormData();form.append('file',file,file.name);this.http.post<any>('/api/v1/admin/catalog/products/import',form).subscribe({next:report=>{this.productImportReport=report;this.error='';this.loadProducts()},error:e=>this.error=e.error?.message??e.error?.detail??'Could not import products.'})}

 duplicateProduct(product:Product):void{const name=prompt('Name for the unpublished product copy',product.name+' copy');if(!name?.trim())return;const sku=prompt('New unique SKU',product.sku+'-COPY');if(!sku?.trim())return;this.http.post<Product>(`/api/v1/products/${product.id}/duplicate`,{name:name.trim(),description:product.description,sku:sku.trim()}).subscribe({next:()=>{this.error='Product copy created as an unpublished draft.';this.loadProducts()},error:e=>this.error=e.error?.message??e.error?.detail??'Could not duplicate product.'})}
 toggle(p:Product):void{this.http.put(`/api/v1/products/${p.id}/active`,{active:!p.active}).subscribe(()=>this.loadProducts())}
 archiveProduct(p:Product):void{if(!window.confirm(`Archive ${p.name}? Its SKU and order history will be retained.`))return;this.http.put(`/api/v1/products/${p.id}/archive`,{}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not archive product.'})}
 restoreProduct(p:Product):void{this.http.put(`/api/v1/products/${p.id}/restore`,{}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not restore product.'})}
 createVariant(product:Product):void{const name=prompt('Variant name');if(!name?.trim())return;const sku=prompt('Unique variant SKU',`${product.sku}-${name.trim().toUpperCase().replace(/[^A-Z0-9]+/g,'-')}`);if(!sku?.trim())return;const raw=prompt('Variant options as JSON using active attribute codes (for example {\"color\":\"navy\",\"size\":\"M\"})','{}');if(raw===null)return;const attributes=this.parseVariantAttributes(raw);if(attributes===null)return;this.http.post(`/api/v1/products/${product.id}/variants`,{name:name.trim(),sku:sku.trim(),attributes}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not create the variant.'})}
 editVariant(variant:{id:string;name:string;sku:string;attributes?:Record<string,string>}):void{const name=prompt('Variant name',variant.name);if(!name?.trim())return;const sku=prompt('Unique variant SKU',variant.sku);if(!sku?.trim())return;const raw=prompt('Variant options JSON',JSON.stringify(variant.attributes??{}));if(raw===null)return;const attributes=this.parseVariantAttributes(raw);if(attributes===null)return;this.http.put(`/api/v1/variants/${variant.id}`,{name:name.trim(),sku:sku.trim(),attributes}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not update the variant.'})}
 parseVariantAttributes(raw:string):Record<string,string>|null{try{const value=JSON.parse(raw);if(!value||Array.isArray(value)||typeof value!=='object'||Object.values(value).some(item=>typeof item!=='string'))throw new Error();return value as Record<string,string>}catch{this.error='Variant options must be a JSON object with string values.';return null}}
 toggleVariant(variant:{id:string;active:boolean}):void{this.http.put(`/api/v1/variants/${variant.id}/active`,{active:!variant.active}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not update variant status.'})}
 schedulePublication(product:Product):void{const localTime=prompt('Publish at local date/time (YYYY-MM-DDTHH:mm)',new Date(Date.now()+3600000-Date.now()%60000).toLocaleString('sv-SE').replace(' ','T').slice(0,16));if(!localTime)return;const publishAt=new Date(localTime);if(Number.isNaN(publishAt.getTime())||publishAt.getTime()<=Date.now()){this.error='Choose a valid future publication time.';return}this.http.put(`/api/v1/products/${product.id}/publication-schedule`,{publishAt:publishAt.toISOString()}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not schedule publication.'})}
 cancelPublication(product:Product):void{if(!confirm('Cancel scheduled publication?'))return;this.http.delete(`/api/v1/products/${product.id}/publication-schedule`).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not cancel publication.'})}
 editSeo(product:Product):void{const slug=prompt('Canonical URL slug (lowercase words separated by hyphens)',product.seoSlug??product.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''));if(!slug?.trim())return;const title=prompt('SEO title (up to 180 characters)',product.seoTitle??product.name);if(title===null)return;const description=prompt('SEO description (up to 320 characters)',product.seoDescription??product.description);if(description===null)return;this.http.put(`/api/v1/products/${product.id}/seo`,{slug:slug.trim(),title:title.trim()||null,description:description.trim()||null}).subscribe({next:()=>this.loadProducts(),error:e=>this.error=e.error?.message??e.error?.detail??'Could not save SEO metadata.'})}
 editTranslations(product:Product):void{this.translationProduct=product;this.translationLocale='de';this.loadTranslation()}
 loadTranslation():void{if(!this.translationProduct)return;this.translationDraft={name:'',description:'',seoSlug:'',seoTitle:'',seoDescription:''};this.http.get<Array<{locale:string;name:string;description:string;seoSlug:string|null;seoTitle:string|null;seoDescription:string|null}>>(`/api/v1/products/${this.translationProduct.id}/translations`).subscribe({next:items=>{const found=items.find(item=>item.locale===this.translationLocale);if(found)this.translationDraft={name:found.name,description:found.description,seoSlug:found.seoSlug??'',seoTitle:found.seoTitle??'',seoDescription:found.seoDescription??''}},error:()=>this.error='Could not load product translations.'})}
 saveTranslation():void{if(!this.translationProduct)return;this.http.put(`/api/v1/products/${this.translationProduct.id}/translations/${this.translationLocale}`,this.translationDraft).subscribe({next:()=>this.error='',error:e=>this.error=e.error?.message??e.error?.detail??'Could not save product translation.'})}
 registerExtension():void{try{const manifest=JSON.parse(this.extensionManifestJson);this.http.post('/api/v1/admin/extensions/register',manifest).subscribe({next:()=>{this.showExtensionRegistration=false;this.extensionManifestJson='';this.error='';this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??'Manifest validation or registration failed.'})}catch{this.error='Extension manifest must be valid JSON.'}}
 selectExtension(extension:any):void{this.http.get<any>(`/api/v1/admin/extensions/${extension.id}`).subscribe({next:plugin=>{this.selectedExtension=plugin;this.extensionConfig={...plugin.configuration};for(const key of Object.keys(plugin.manifest.configuration??{})){if(plugin.manifest.configuration[key].type==='secret')this.extensionConfig[key]=''}},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load extension settings.'})}
 saveExtensionConfiguration():void{if(!this.selectedExtension)return;const payload={...this.extensionConfig};for(const key of this.selectedExtension.configuredSecrets){if(!payload[key])delete payload[key]}this.http.put(`/api/v1/admin/extensions/${this.selectedExtension.manifest.id}/configuration`,payload).subscribe({next:()=>{this.error='';this.selectedExtension=null;this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??'Extension configuration is invalid.'})}
 openObservability():void{const popup=window.open('about:blank','_blank');if(!popup){this.error='Allow pop-ups to open observability dashboards.';return}popup.opener=null;this.http.get('/api/v1/admin/extensions/observability.artio/ui-session').subscribe({next:()=>{popup.location.href='/plugins/observability/'},error:e=>{popup.close();this.error=e.error?.message??e.error?.detail??'Could not open observability dashboards.'}})}
 extensionAction(extension:any,action:'install'|'enable'|'disable'):void{this.http.post(`/api/v1/admin/extensions/${extension.id}/${action}`,{}).subscribe({next:()=>{this.error='';this.extensionHealth='';this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??e.error?.message??`Could not ${action} extension.`})}
 updateExtension(extension:any):void{const manifestJson=window.prompt(`Paste the next manifest JSON for ${extension.id}`);if(!manifestJson)return;try{const manifest=JSON.parse(manifestJson);this.http.post(`/api/v1/admin/extensions/${extension.id}/update`,manifest).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??e.error?.message??'Could not update extension.'})}catch{this.error='Manifest must be valid JSON.'}}
 rollbackExtension(extension:any):void{if(!window.confirm(`Roll back ${extension.id} to its previous release?`))return;this.http.post(`/api/v1/admin/extensions/${extension.id}/rollback`,{}).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??e.error?.message??'Could not roll back extension.'})} uninstallExtension(extension:any):void{if(!window.confirm(`Remove ${extension.name}? This stops and removes its managed container and purges stored configuration.`))return;this.http.delete(`/api/v1/admin/extensions/${extension.id}`).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??e.error?.message??'Could not uninstall extension.'})} rotateExtensionCredentials(extension:any):void{this.http.post(`/api/v1/admin/extensions/${extension.id}/credentials/rotate`,{}).subscribe({next:()=>{this.error='';this.extensionHealth=`${extension.id}: credential rotated`;this.loadExtensions()},error:e=>this.error=e.error?.message??e.error?.detail??e.error?.message??'Could not rotate extension credential.'})}
 checkExtensionHealth(extension:any):void{this.http.get<any>(`/api/v1/admin/extensions/${extension.id}/health`).subscribe({next:r=>{this.extensionHealth=`${extension.id}: ${r.healthy?'healthy':r.status}`;this.error=''},error:e=>this.error=e.error?.message??e.error?.detail??'Could not read extension health.'})}
 createBundle():void{const ids=[...this.bundleSellables];if(!ids.length){this.error='Choose at least one variant for this bundle.';return;}const body=this.bundleDraft.type==='FIXED'?{name:this.bundleDraft.name,sku:this.bundleDraft.sku,type:'FIXED',pricingRule:{mode:'COMPONENT_SUM'},components:ids.map((sellableId:string)=>({sellableId,quantity:1})),optionGroups:[]}:{name:this.bundleDraft.name,sku:this.bundleDraft.sku,type:'CONFIGURABLE',pricingRule:{mode:'COMPONENT_SUM'},components:[],optionGroups:[{code:'choices',name:'Choose your items',minimumSelections:1,maximumSelections:ids.length,choices:ids.map((sellableId:string)=>({sellableId,quantity:1}))}]};this.http.post('/api/v1/bundles',body).subscribe({next:()=>{this.showBundle=false;this.loadBundles()},error:e=>this.error=e.error?.message??e.error?.detail??'Could not create bundle.'})}
 editBundleTranslation(bundle:any):void{this.bundleTranslationBundle=bundle;this.bundleTranslationLocale='de';this.loadBundleTranslation()}
 loadBundleTranslation():void{if(!this.bundleTranslationBundle)return;this.bundleTranslationDraft={name:'',optionGroupNames:{}};this.http.get<any>(`/api/v1/bundles/${this.bundleTranslationBundle.id}/translations/${this.bundleTranslationLocale}`).subscribe({next:r=>this.bundleTranslationDraft={name:r.name??'',optionGroupNames:{...(r.optionGroupNames??{})}},error:e=>this.error=e.error?.message??e.error?.detail??'Could not load bundle translations.'})}
 saveBundleTranslation():void{if(!this.bundleTranslationBundle)return;this.http.put(`/api/v1/bundles/${this.bundleTranslationBundle.id}/translations/${this.bundleTranslationLocale}`,this.bundleTranslationDraft).subscribe({next:()=>this.error='',error:e=>this.error=e.error?.message??e.error?.detail??'Could not save bundle translations.'})} activateBundle(b:any):void{this.http.put(`/api/v1/bundles/${b.id}/active`,{active:!b.active}).subscribe(()=>this.loadBundles())}
 createPrice():void{if(!this.priceDraft.sellableId){this.error='Choose a product variant.';return;}this.http.post('/api/v1/prices',{...this.priceDraft,sellableId:this.priceDraft.sellableId,amount:Number(this.priceDraft.amount)}).subscribe({next:()=>{this.showPrice=false;this.loadPrices()},error:e=>this.error=e.error?.message??e.error?.detail??'Could not create price.'})}
 assignTaxCategory():void{if(!this.taxAssignment.sellableId){this.error='Choose a product variant.';return;}this.http.put(`/api/v1/tax-rules/sellables/${this.taxAssignment.sellableId}/category`,{category:this.taxAssignment.category}).subscribe({next:()=>{this.error='';this.taxAssignment={sellableId:'',category:'STANDARD'};this.loadPrices()},error:e=>this.error=e.error?.message??e.error?.detail??'Could not assign tax category.'})}
}
